def button(text,link='/contact/',cls='button'):
 return f'<a class="{cls}" href="{link}"><span>{text}</span> {ARR}</a>'
def photo(name,alt,cl='',eager=False,w=1800,h=1350,sizes='(max-width:700px) 100vw, 60vw'):
 small=800 if w>h else 600
 mid=1200
 load='eager" fetchpriority="high' if eager else 'lazy'
 return f'<img class="{cl}" src="/assets/{name}.webp" srcset="/assets/{name}-800.webp {small}w, /assets/{name}-1200.webp {mid}w, /assets/{name}.webp {w}w" sizes="{sizes}" alt="{alt}" width="{w}" height="{h}" loading="{load}">'
def figure(n,name,alt,caption,cap_dialog,cl='',w=1800,h=1350,sizes='(max-width:700px) 100vw, 60vw'):
 return f'<figure class="fig reveal img {cl}"><button class="image-button" data-image="/assets/{name}.webp" data-caption="{cap_dialog}">'+photo(name,alt,w=w,h=h,sizes=sizes)+f'<span class="zoom">Vergroten {ARR}</span></button><figcaption><b>{n}</b>{caption}</figcaption></figure>'
def intro(kicker,title,desc):
 return f'<section class="page-intro"><div class="wrap"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lead">{desc}</p></div></section>'
