notice='<p class="editor-note">Voorstel op basis van de projectfoto’s. De precieze diensten en werkwijze worden nog door Daan bevestigd.</p>'
comparison='<div class="duo">'+figure('01','dak-voor','Grijs pannendak met zichtbaar mos','Met mos','Dak met zichtbaar mos','duo-a',sizes='(max-width:700px) 100vw, 58vw')+figure('02','dak-resultaat','Hetzelfde grijze pannendak zonder het zichtbare mos','Gereinigd dakvlak','Hetzelfde dak zonder het zichtbare mos','duo-b',sizes='(max-width:700px) 90vw, 40vw')+'</div>'
steps='''<ol class="steps"><li class="reveal"><span class="step-num">01</span><h3>Vertel wat u nodig hebt.</h3><p>Geef uw gemeente door en omschrijf kort de werkzaamheden. Foto’s helpen om de situatie te bekijken.</p></li><li class="reveal"><span class="step-num">02</span><h3>Bespreek de mogelijkheden.</h3><p>Stem met Daan af welke aanpak bij uw project past en wat nodig is voor een offerte.</p></li><li class="reveal"><span class="step-num">03</span><h3>Maak duidelijke afspraken.</h3><p>Na akkoord spreekt u samen de werkzaamheden en de planning af.</p></li></ol>'''
